import {today,daysLeft,foods,plan,cook,demo,validate} from './engine.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],key='shelfshift-v1';
const icons={tomato:'🍅',spinach:'🥬',eggs:'🥚',bread:'🍞',rice:'🍚',carrot:'🥕',pasta:'🍝',banana:'🍌',oats:'🌾',milk:'🥛',lentils:'🫘',chickpeas:'🫘'};
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state={version:1,pantry:[],history:[]},filter='all',ideas=[],undoState=null,storageOK=true;
try{const saved=localStorage.getItem(key);if(saved)state=validate(JSON.parse(saved));}catch(e){storageOK=false;message('Saved data could not be loaded. Restore a valid backup, or add ingredients to start again.',true)}
function message(s,error=false){$('#notice').textContent=s;$('#notice').className=error?'error':'';}
function save(){try{localStorage.setItem(key,JSON.stringify(state));storageOK=true;}catch(e){storageOK=false;message('Storage is unavailable. Changes are in memory only: export a backup before closing.',true)}$('.local').innerHTML=storageOK?'<i></i> Saved on this device':'In memory · export to keep';render();}
function show(view){['pantry','meals','impact'].forEach(v=>$('#'+v+'-view').hidden=v!==view);$$('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));if(view==='meals')renderMeals();if(view==='impact')renderImpact();}
function stat(value,label,sub,glyph){return `<div class="stat"><div><strong>${value}</strong> <b>${label}</b><small>${sub}</small></div><span class="glyph">${glyph}</span></div>`}
function render(){const soon=state.pantry.filter(x=>daysLeft(x.date)>=0&&daysLeft(x.date)<=2);$('#stats').innerHTML=stat(state.pantry.length,'ingredients','A little potential on every shelf','✳')+stat(soon.length,'to use soon','Your next two days, sorted','◷')+stat((state.history.reduce((a,h)=>a+h.grams,0)/1000).toFixed(2),'kg used','From meals you’ve logged','↗');renderPantry();renderMeals();renderImpact();}
function renderPantry(){let list=[...state.pantry].sort((a,b)=>a.date.localeCompare(b.date)).filter(x=>filter==='all'||filter==='soon'&&daysLeft(x.date)>=0&&daysLeft(x.date)<=2||filter==='expired'&&daysLeft(x.date)<0);$('#pantry-count').textContent=list.length+' ingredients';$('#pantry').innerHTML=list.map(x=>{const d=daysLeft(x.date);return `<article class="pantry-card"><button class="remove" data-remove="${esc(x.id)}" aria-label="Remove ${esc(x.food)}">×</button><div class="food-icon" aria-hidden="true">${icons[x.food]}</div><h3>${esc(x.food)}</h3><span class="weight">${x.grams} g available</span><div class="date-row"><span>${esc(x.date)}</span><span class="badge ${d<0?'expired':d<=2?'soon':''}">${d<0?'Past date':d===0?'Use today':d<=2?'Use in '+d+'d':d+' days left'}</span></div></article>`}).join('')||'<div class="empty"><h3>A little space for possibility.</h3><p>Add ingredients or load the sample pantry to start.<br>Meal ideas grow from what you already have.</p></div>';}
function settings(){return {people:Number($('#people').value),diet:$('#diet').value,maxTime:Number($('#time').value)}}
function renderMeals(){ideas=plan(state.pantry,settings());$('#meals').innerHTML=ideas.map((r,i)=>`<article class="meal"><div class="meal-top"><span class="meal-icon">${r.icon}</span><span class="badge ${r.missing.length?'soon':''}">${r.missing.length?'Needs '+r.missing.length+' ingredient'+(r.missing.length===1?'':'s'):'Ready to cook'}</span></div><h3>${r.name}</h3><p>${r.time} min · ${$('#people').value} people · ${r.kind}<br><strong>${r.grams}g</strong> from your pantry<br><strong>${r.urgent}g</strong> of it due within 2 days</p><button data-recipe="${i}">See recipe & ingredients ↗</button></article>`).join('')||'<div class="empty"><h3>No matches yet.</h3><p>Add more ingredients, allow more time, or adjust your eating preference.</p></div>';}
function renderImpact(){const total=state.history.reduce((a,h)=>a+h.grams,0),urgent=state.history.reduce((a,h)=>a+h.urgent,0);$('#impact').innerHTML=`<div class="impact-panel"><p class="eyebrow">REPORTED FOOD USE</p><div class="impact-number">${(total/1000).toFixed(2)} <span style="font-size:26px;letter-spacing:0">kg</span></div><p>${state.history.length} meals logged · ${(urgent/1000).toFixed(2)} kg used near its entered date</p><p class="quiet-note">Start with a seven-day baseline of food discarded, then compare weekly discarded grams after using ShelfShift. This prototype records cooking; it does not yet measure that change.</p></div>`;$('#history').innerHTML=state.history.map(h=>`<div class="journal-row"><div>${esc(h.name)}<small>${esc(h.date)}</small></div><span>${h.grams}g used · ${h.urgent}g near date</span></div>`).join('')||'<div class="empty">Your first logged meal starts your journal.</div>';$('#undo').disabled=!undoState;}
$$('nav button').forEach(b=>b.onclick=()=>show(b.dataset.view));$$('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;$$('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));renderPantry()});$('#hero-plan').onclick=()=>{show('meals');$('#meals-view').scrollIntoView({behavior:'smooth'})};
$('#food').innerHTML=foods.map(f=>`<option value="${f}">${f[0].toUpperCase()+f.slice(1)}</option>`).join('');$('#date').value=today();$('#add-open').onclick=()=>$('#add-dialog').showModal();$('#add-close').onclick=()=>$('#add-dialog').close();$('#add-form').onsubmit=e=>{e.preventDefault();const item={id:crypto.randomUUID(),food:$('#food').value,grams:Number($('#grams').value),date:$('#date').value};try{validate({...state,pantry:[...state.pantry,item]});state.pantry.push(item);undoState=null;save();$('#add-dialog').close();$('#grams').value='';message('Ingredient added. Your meal ideas are up to date.')}catch(e){message(e.message,true)}};
$('#demo').onclick=()=>{if(state.pantry.length||state.history.length){if(!confirm('Replace this pantry and cooking history with sample data? Export a backup first if you want to keep them.'))return;}state=demo();undoState=null;save();message('Sample pantry loaded. Dates are relative to today; cooking history starts empty.');};
$('#pantry').onclick=e=>{const b=e.target.closest('[data-remove]');if(!b)return;state.pantry=state.pantry.filter(x=>x.id!==b.dataset.remove);undoState=null;save();message('Ingredient removed from the pantry. This is not recorded as food used.');};
$('#plan-form').onsubmit=e=>{e.preventDefault();renderMeals();message('Meal ideas refreshed from your current pantry.');};
$('#meals').onclick=e=>{const b=e.target.closest('[data-recipe]');if(!b)return;const r=ideas[Number(b.dataset.recipe)];$('#recipe-detail').innerHTML=`<p class="eyebrow">${r.time} MINUTES · ${$('#people').value} PEOPLE</p><h2>${r.name}</h2><h3>From your pantry</h3><ul>${r.used.map(u=>`<li>${u.grams}g ${u.food} · ${u.date}</li>`).join('')}</ul>${r.missing.length?'<h3>Add these first</h3><ul>'+r.missing.map(u=>`<li>${u.grams}g ${u.food}</li>`).join('')+'</ul>':''}<h3>Make it</h3><ol>${r.steps.map(x=>`<li>${x}</li>`).join('')}</ol><p class="quiet-note">${r.tip} Check allergen labels and safe storage. Eating preferences are ingredient filters, not allergen guarantees.</p><button id="cook" class="primary" ${r.missing.length?'disabled':''}>I cooked this · log ${r.grams}g used</button><p class="quiet-note">Log only after cooking. This deducts the exact pantry quantities shown above.</p>`;$('#cook').onclick=()=>{try{const next=cook(state,r);undoState=structuredClone(state);state=next;save();$('#recipe-dialog').close();message('Meal logged. Pantry quantities updated. Undo is available in Your impact.');show('impact');}catch(e){message(e.message,true);$('#recipe-dialog').close();renderMeals();}};$('#recipe-dialog').showModal();};$('#recipe-close').onclick=()=>$('#recipe-dialog').close();$('#undo').onclick=()=>{if(!undoState)return;state=undoState;undoState=null;save();message('Last meal undone. Its ingredient quantities have been restored.');};
$('#export').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='shelfshift-'+today()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);message('Backup exported. Keep this file to restore on another device.');};$('#import').onclick=()=>$('#backup').click();$('#backup').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>2000000)throw Error('Backup must be smaller than 2 MB.');const next=validate(JSON.parse(await file.text()));if(!confirm('Replace your current pantry and history with this backup?'))return;state=next;undoState=null;save();message('Backup restored. Your pantry and history are ready.');}catch(e){message('Restore failed: '+e.message,true);}finally{e.target.value=''}};
render();
